"""Pin the settings-tool row validators against the shipped Node runtime.

`python/cinbase/config/js/config.js` decides by hand which rows of the
custom extend table (checkType ``"3"``, the 自訂擴展碼表 textarea) and the
easy-symbol table (checkType ``"1"``, the 簡易符號 textarea) are well
formed. Upstream issue #853 reported that the leading-key class of the
extend-table gate rejects codes real tables carry: the 大易 row ``;c 能``
and the 傳統注音 row ``1/4 泵``. The pins below drive the real function with
the bundled `node/node.exe`, following the harness pattern of
`tests/test_config_tool_js.py`: stub the handful of jQuery/DOM touches the
file makes at load, ``eval`` the source, call ``checkDataFormat``, and
report the collected jAlert texts.

A missing bundled node skips cleanly, as elsewhere in this harness.
"""

import os
import unittest

from settings_js_harness import settings_prelude, run_node_script

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
CINBASE_CONFIG_JS = os.path.join(ROOT, "python", "cinbase", "config", "js", "config.js")


def build_harness():
    """node -e program: eval config.js, call checkDataFormat per pin.

    The stubs cover exactly the statements the file runs at load
    (hasInnerText, the isIE probe, includeScriptFile, loadConfig) plus the
    two touches the validator makes: $.jAlert collects the error texts and
    the $(elementId) object answers blur()/prop() on the error path.
    """
    long_value = "新" * 41
    lines = settings_prelude(CINBASE_CONFIG_JS) + [
        "var results = [];",
        "function run(data, type) {",
        "  alerts.length = 0;",
        "  var ret = checkDataFormat(data, type, '#pinned', '測試');",
        "  results.push({ ret: ret, alerts: alerts.slice() });",
        "}",
        # extend table (checkType "3"): rows the real tables carry.
        "run(';c 能', '3');",
        "run('1/4 泵', '3');",
        "run('aa 大易', '3');",
        # extend table: still-rejected rows.
        "run(';c能', '3');",
        "run('\\n\\n', '3');",
        "run('aa %s', '3');" % long_value,
        # easy symbols (checkType "1"): widened root, value bound kept.
        "run('1 一', '1');",
        "run('m 新酷音新酷音新酷音新', '1');",
        "run('m 新酷音新酷音新酷音新酷', '1');",
        "console.log(JSON.stringify(results));",
    ]
    return "\n".join(lines)


class CheckDataFormatPinsTests(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        cls.results = run_node_script(build_harness())

    def _accepted(self, index, label):
        self.assertEqual(True, self.results[index]["ret"],
                         "%s must be accepted" % label)
        self.assertEqual([], self.results[index]["alerts"],
                         "%s must raise no alert" % label)

    def _rejected_once(self, index, label):
        self.assertEqual(False, self.results[index]["ret"],
                         "%s must be rejected" % label)
        self.assertEqual(1, len(self.results[index]["alerts"]),
                         "%s must raise exactly one alert" % label)

    def test_extend_table_accepts_reporter_rows(self):
        """#853: the semicolon root of 大易 and the digits/slash roots of
        傳統注音 are what the widened leading-key class must let through."""
        self._accepted(0, ";c 能")
        self._accepted(1, "1/4 泵")
        self._accepted(2, "aa 大易 (ordinary alnum row)")

    def test_extend_table_rejects_malformed_rows(self):
        """The space separator, the empty-block exemption and the 40-char
        value bound keep their bite after the widening."""
        self._rejected_once(3, ";c能 (no space)")
        self.assertIn(";c能", self.results[3]["alerts"][0])
        self.assertIn("英數符號 + 空格 + 字詞", self.results[3]["alerts"][0])
        # "\n\n" splits to three empty lines, so the single-empty-line
        # exemption does not apply and the empty-line alert fires.
        self._rejected_once(4, "empty multi-line block")
        self.assertIn("空行", self.results[4]["alerts"][0])
        self.assertIn("英數符號 + 空格 + 字詞", self.results[4]["alerts"][0])
        self._rejected_once(5, "41-char value")
        self.assertIn("格式錯誤", self.results[5]["alerts"][0])

    def test_easy_symbols_root_is_alphanumeric_plus_symbol(self):
        """checkType "1" (the 簡易符號 surface) keeps the 1..10 value bound
        while the root class matches the extend table's widened one."""
        self._accepted(6, "1 一")
        self._accepted(7, "m <10-char value>")
        self._rejected_once(8, "m <11-char value>")


if __name__ == "__main__":
    unittest.main()
